_MASK = None

def mask():
    global _MASK
    if _MASK is None:
        m, v = (bytearray(), 0)
        for n in RUNS.replace('\n', '').split(','):
            m += bytes([v]) * int(n)
            v ^= 1
        assert len(m) == SIZE[0] * SIZE[1]
        _MASK = m
    return _MASK

def cloth(r, g, b):
    import colorsys
    lum = (0.3 * r + 0.59 * g + 0.11 * b) / 255
    nr, ng, nb = colorsys.hsv_to_rgb(HUE % 360 / 360, SAT, min(1.0, VAL * (lum / LUM_MID) ** 0.8))
    return (int(nr * 255), int(ng * 255), int(nb * 255))
